local encoded = [[]]
local mask = {104,153,183,52,160,120,161,173,179,205,135,108,190,86,196,38,185,2,111,152,175,214,160,141,232,202,206,91,177,169,195,44}
local alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local lookup = {}
for index = 1, #alphabet do lookup[string.byte(alphabet, index)] = index - 1 end
local bytes, pieces = {}, {}
local count = 0
local function emit(value)
    count += 1
    bytes[#bytes + 1] = bit32.bxor(value, mask[(count - 1) % #mask + 1])
    if #bytes == 192 then
        pieces[#pieces + 1] = string.char(table.unpack(bytes))
        table.clear(bytes)
    end
end
for index = 1, #encoded, 4 do
    local a, b, c, d = string.byte(encoded, index, index + 3)
    local value = lookup[a] * 262144 + lookup[b] * 4096
        + (lookup[c] or 0) * 64 + (lookup[d] or 0)
    emit(math.floor(value / 65536) % 256)
    if c ~= 61 then emit(math.floor(value / 256) % 256) end
    if d ~= 61 then emit(value % 256) end
end
if #bytes > 0 then pieces[#pieces + 1] = string.char(table.unpack(bytes)) end
assert(count == 271482, 'Madness: truncated release payload')
local source = table.concat(pieces)
encoded, mask, lookup, bytes, pieces = nil, nil, nil, nil, nil
local chunk, problem = loadstring(source, '@Madness.lua')
source = nil
if not chunk then error('Madness: payload compilation failed: ' .. tostring(problem), 0) end
return chunk()
